from pathlib import Path
import json,hashlib,copy
out=Path('docs/research/frame-pass3/continuation');out.mkdir(exist_ok=True);base=json.loads(Path('docs/research/expansion/yamaha/workshop-pass2/airbox-remove-refit-v1.procedure.json').read_text());url=base['source']['source_url']
def step(id,title,text,pages,check,record=False,diagram=False):return dict(id=id,title=title,instruction=text,source_pdf_pages=pages,verification=[check],record_required=record,diagram_reference_required=diagram,source_links=[url+f'#page={n}' for n in pages] if diagram else [],origin='Original OEM-based summary; record prompts and sealed-assembly handling are explicit workshop workflow adaptations.')
def emit(name,title,scope,steps,exclusions,tools,parts=[],dependencies=[]):
 p={k:copy.deepcopy(base[k]) for k in ['schema_version','target','scope_confirmed','status','publication_status','source']};p.update(id='yamaha-2026-yz450f-'+name,title=title,completeness=scope,applicability={'included':'Exact stock 2026 US standard YZ450F; original serviceable assemblies unless explicitly replaced below','excluded':['Other years/models and non-stock assemblies','Frame repair/welding/straightening']+exclusions},prerequisites=['Match the exact bike and installed stock parts. Have the complete cited diagrams available.','Stable maintenance stand and support suitable for changing weight distribution; clean labeled parts storage.'],required_tools=[{'name':x,'spec':None} for x in tools],required_parts=parts,critical_stop_conditions=['Unstable support, bent/cracked parts, damaged fasteners or unknown assembly order.','Binding, leaks, missing hardware or abnormal brake/control function remains an unresolved fault.'],steps=steps,operation_dependencies=dependencies)
 for i,s in enumerate(steps):s['depends_on']=[steps[i-1]['id']] if i else []
 p['source']['pdf_pages']=sorted(set(n for s in steps for n in s['source_pdf_pages']));p['source']['printed_pages']=['See exact PDF page links at each step'];p['source']['review_note']='Text and assembly diagrams visually checked for this bounded operation; no generalization to other years or modified parts.'
 path=out/(name+'.procedure.json');path.write_text(json.dumps(p,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');return p
root=Path('docs/research/frame-pass3')
eng=json.loads((root/'engine-remove-refit-v1.procedure.json').read_text());steer=json.loads((root/'steering-bearing-inspection-v1.procedure.json').read_text());swing=json.loads((root/'swingarm-linkage-remove-refit-v1.procedure.json').read_text());rear=json.loads((root/'rear-wheel-remove-refit-v1.procedure.json').read_text())
def named(p,id):return copy.deepcopy(next(s for s in p['steps'] if s['id']==id))
def span(p,start,end,prefix):
 ids=[s['id'] for s in p['steps']];result=copy.deepcopy(p['steps'][ids.index(start):ids.index(end)+1])
 for s in result:s['id']=prefix+s['id']
 return result
frame=span(eng,'initial-record','engine-out','engine-')
frame+=span(rear,'prepare','inspect','rear-')
frame += [step('rear-brake-free','Free the complete rear brake assembly','With the rear wheel removed, slide the complete caliper/bracket off its swingarm guide and release the hose retaining clamps. The pedal pivot/spring were already removed during engine access. Remove the two rear-master-cylinder mounting bolts and support master, hose, caliper and linked pedal together. Keep hose unions, reservoir, pads and pushrod pin attached; do not pump the pedal.',[61,76,77,134,150,152,153,210],'Entire rear brake assembly supported off frame/swingarm; hydraulic circuit remains closed.',False,True)]
frame += span(swing,'shock-lower','shock-lower','rear-')
frame += [step('swingarm-off','Remove the supported swingarm','The engine pivot is already withdrawn. Support the arm while removing the temporary support shaft used for engine removal, then lower the swingarm clear. Keep original collars and thrust-bearing/seal stacks with their correct sides. The intact linkage is already free; do not extract its bearings or seals.',[187,194,195,211],'Temporary pivot removed; supported arm clear; all stacks labeled.',False,True),named(swing,'arm-inspect'),step('shock-upper-off','Remove the sealed shock','Support the shock, remove its upper nut/bolt and lift out the complete sealed assembly. Its lower bolt was removed with the linkage. Keep original eyelet collars/seals intact; do not release gas or loosen the preload hardware.',[185,188,190],'Sealed shock and upper hardware supported and retained.',False,True)]
frame += span(steer,'setup','steering-inspect','front-')
frame += [
 step('radiators-off','Remove the radiators and remaining hose connections','Coolant was drained during engine access. Label all four hoses1–4 and every remaining clamp orientation using the source diagram. Release the remaining radiator-side hose joints and the radiator breather. Support each radiator, remove its two mounting bolts, and retain each damper/collar/washer stack. Lift both radiators and the loose hoses clear. Leave the coolant pipe joints and their O-rings on the removed engine.',[57,296,297],'Both radiators/hoses labeled; four mount stacks retained; engine pipe seals untouched.',False,True),
 step('rear-electrical-free','Release the rear electrical attachments','Battery leads are isolated. Release the battery band and lift out the battery. Unplug ECU, CCU and starter-relay harness couplers, releasing their covers first; retain the electronics in their original holders on the rear frame. Release the white/green-tape harness ties and clip so the main loom is free of the rear frame. Keep starter/positive leads on the relay and carry them with the rear frame; the starter lead is already free at the engine.',[66,67,74,75,123,124],'Battery removed; rear couplers identified; loom/ties released; relay leads supported.',False,True),
 step('rear-frame-off','Remove the rear-frame assembly','Support the rear frame with rear fender/holders attached. Remove the upper chain tensioner retaining pin and washer, then slide off its roller from the rear-frame bolt; prepare a new pin. Remove all four rear-frame bolts and lift the assembly clear, checking no wire, silencer or hose remains attached. Keep each bolt with its original position.',[62,124,127,128],'Rear-frame assembly clear; four bolts mapped; upper roller/washer retained; new pin ready.',False,True),
 step('loom-control-off','Lift the supported controls and main harness clear','The bar is already free of its holders, throttle body off its joint, front caliper free, and clutch release off the engine. Release the remaining frame/cable holders and plastic ties according to the front-left, right and top routing diagrams. Unbolt the rectifier/regulator, ignition-coil bracket and air-filter-case brackets from the frame, retaining the coils and connectors on their bracket where possible. Lift the supported harness, bar/controls, throttle body and closed front-brake/clutch assemblies clear as a connected group; use separate bench supports so no cable/hose bears another part\'s weight. If any stock routing prevents removal without disconnecting a hydraulic joint or throttle end, this retained-assembly variant stops here rather than improvising.',[57,59,63,64,65,68,69,70,71,72,73,161,162,208,310],'All frame holders released; intact controls/hydraulics supported; harness and brackets clear without tension.',False,True),
 step('remaining-brackets','Remove the remaining bolt-on frame parts','Remove each complete footrest bracket with its peg, spring and pin still assembled; retain the four bracket bolts by side. Remove the lower chain-tensioner bolt and intact roller/collar stack. Identify and retain any remaining clip-in harness holders and removable rubber mounting pieces in labeled positions. Pressed steering races and bonded frame pads may remain; this is not a paint-stripping or structural repair operation.',[61,62,63,124],'Footrest assemblies and lower roller removed; remaining frame attachments recorded.',True,True),
 step('frame-inspection','Inspect the exposed main frame','Clean the exposed frame and mounting interfaces without removing identification markings. Record cracks, bends, damaged threads, corroded mounting points or fretting. This guide only reassembles a serviceable original frame; it supplies no frame-alignment tolerance, welding method or straightening authorization. Verify the separate engine work and all component repair findings before reassembly.',[90,91,182,194],'Frame condition and component repair status recorded; no structural fault silently accepted.',True),
 step('frame-small-refit','Restore footrests, roller and retained mounting pieces','Return all labeled rubber pieces and clip-in holders to their original positions. Refit the intact footrest brackets with source-specified LOCTITE on the four bolts and tighten55 N·m. Refit the intact lower chain-tensioner roller and collar stack and tighten its bolt16 N·m; check the roller turns correctly.',[61,62,124],'Footrest bolts55 N·m; lower roller16 N·m and free; original mount pieces restored.',False,True),
 step('rear-frame-refit','Reinstall the rear frame and upper roller','Align the supported rear frame without trapping wires. Return its four bolts to their mapped positions and tighten38 N·m. Install the upper chain tensioner and washer on its correct bolt, then install a new retaining pin through the outside pin hole as illustrated; the inside hole is the documented alternative if necessary. Bend the pin so its tip stays within the roller\'s outer diameter.',[62,124,127,128],'Four rear-frame bolts38 N·m; roller/washer/new pin correctly retained.',False,True),
 step('loom-control-refit','Place the controls, loom and brackets back on the frame','Place the intact supported bar/control and hydraulic assemblies near their original locations, keeping them independently supported until mounted. Route the main loom along the original frame/tank-rail path and engage its locating projections. Refit the original air-filter-case brackets, rectifier/regulator and ignition-coil bracket at7 N·m for each respective mounting bolt. Do not disturb sensor or throttle adjustment screws. Use the exact diagram rather than crossing the loom over the engine opening.',[57,59,63,64,65,68,69,72,73,208,310],'Bracket mount groups7 N·m; loom located; unsupported units still protected.',False,True),
 step('rear-harness-route','Restore rear harness routing and holders','Restore the harness/starter-lead ties at the white and green tape locations. At the green-tape clip, starter lead lies below the harness; lock faces down and trimmed end outward. Route negative lead along the inside of the starter lead, and positive lead outside the rear-fender projection. Reseat ECU/CCU/relay connectors and covers: ECU holder enters its battery-box bracket with ECU connector toward the left. Fit the battery and band but leave terminal leads isolated until final startup preparation.',[66,67,74,75,123,124],'Rear tie locations/orientations and ECU/CCU/relay holders/covers restored; battery remains isolated.',False,True),
 step('radiators-refit','Mount the radiators and route their hoses','Inspect hoses and mounting dampers for damage. Restore the original damper/collar/washer stacks and tighten the four radiator mounting bolts10 N·m. Return hoses1–4 to their labeled radiator ends, preserving the original clamp positions; disturbed hose-clamp screws tighten1.5 N·m. Leave engine-end joints ready for engine installation. Route radiator breather behind the upper boss, ahead of the lower boss and ahead of the radiator hose, then through the down tube as shown.',[57,64,65,68,69,296,297,298],'Radiator mounts10 N·m; radiator-side clamps1.5 N·m; breather and hoses correctly routed.',False,True),
 step('shock-upper-refit','Hang the intact shock on its upper mount','Inspect the retained upper eyelet/collars and lubricate the upper mounting bolt with molybdenum-disulfide grease. Install the bolt from the right and tighten its nut56 N·m. Keep the sealed shock supported until its lower connection is restored; no preload or internal changes are implied.',[188,190],'Upper bolt from right; nut56 N·m; eyelet parts retained.',False,True)
]
frame+=span(steer,'steering-grease','steering-close','front-')
frame += [step('engine-bench-record','Verify the engine and rear bearing stacks','Confirm the documented internal engine work has its own pre-start clearance, timing and free-rotation checks complete. Inspect and grease original serviceable swingarm bearing/thrust/bushing/collar/seal contact surfaces with molybdenum-disulfide grease. Position the independently supported swingarm with its original side stacks so the shared pivot can locate both it and the engine in the next step.',[189,194,195,211,212],'Engine bench record verified; arm stacks lubricated and supported for shared pivot.',True,True)]
frame+=span(eng,'engine-in','mount-torque','engine-')
frame+=span(swing,'link-refit','link-torque','rear-')
frame += [step('rear-brake-refit','Mount the closed rear brake assembly','Refit the rear master cylinder to its frame mount with both mounting bolts10 N·m, keeping its original pushrod/clevis adjustment unchanged. Restore the hose along the swingarm: paint mark up, no interference with the spring or suspension. Seat each retaining clamp fully, latch by at least three notches and face the clamp opening inward. Keep caliper/bracket supported for wheel insertion. Pedal pivot/spring are restored by the engine closure step next.',[61,76,77,152,153],'Master mount bolts10 N·m; closed hose correctly routed; pedal/clevis unchanged.',False,True)]
frame+=span(eng,'release-refit','sprocket-refit','engine-')
frame+=span(rear,'refit','hardware','rear-')
frame+=span(eng,'ground-starter','cooling-cap','engine-')
frame += [step('pressure-test','Pressure-check the reinstalled cooling system','With coolant at the upper level, install the specified radiator tester/adapter and apply137.3 kPa; do not exceed that pressure. It must hold5–10 seconds. Check radiator joints and hoses for leaks or bulging, correct any fault, release pressure and cover the connection with a cloth before removing the tester. Secure the radiator cap. Do not perform this check on a hot pressurized system.',[298,299],'Cooling system holds137.3 kPa for5–10 seconds; no leaks/bulges; cap restored.',True,True)]
frame+=span(eng,'oil-fill','final-checks','engine-')
frame += [step('frame-final','Verify the rebuilt chassis as a whole','Check steering play and lock-to-lock clearance, smooth front/rear suspension, front/rear wheel retention and brake action, chain alignment/slack, footrest return and all disturbed frame/engine/linkage fasteners. Check the throttle returns and idle does not change when steering; inspect fuel/oil/coolant leaks and retained harness/tie clearances. Record every unresolved defect and completed separate engine/component job. This record documents reassembly of serviceable stock assemblies, not structural frame repair or automatic permission to ride.',[90,96,111,112,113,184,190,191,195,299],'Whole-bike mechanical/control/fluid checks recorded; unresolved faults remain open.',True)]
front_route=step('front-control-route','Restore front control routing','Route the throttle cables to the right of the number-plate bracket and the starter-switch lead to its left. Both switch leads pass between the plate routing section and upper bracket. Match the plate markings and drawing: clutch hose on the right, ahead of throttle cables and behind the front brake hose. Restore bar ties with locks downward and ends forward, clear of masters and fork tubes. The front brake hose then returns to the plate guides in the next step.',[70,71],'Cable/lead sides and hose crossing order match the source; ties cannot contact controls or forks.',False,True)
frame.insert(next(i for i,s in enumerate(frame) if s['id']=='front-plate-settings'),front_route)
# Defer fork seating until both wheels and rear assembly have been secured.
late=[next(s for s in frame if s['id']==id) for id in ['front-seat-torque','front-steering-close']]
for item in late:frame.remove(item)
pos=next(i for i,s in enumerate(frame) if s['id']=='engine-torque')+1
frame[pos:pos]=late
# In the composite, avoid presenting a repeated standalone setup as a new task.
for s in frame:
 if s['id']=='rear-harness-route':s['instruction']+=' At the white-tape rear-frame tie, point the lock downward and trimmed end outward as well.'
 if s['id']=='engine-harness-refit':s['instruction']+=' At the lower engine tie between the indicated left-cover bolts, point the lock outward. At the tie above the upper radiator boss, point the lock forward. Keep rectifier/regulator leads inside the tension arm and throttle cables behind the switch leads; align clutch-hose paint marks to the forward-facing clamp.'
 if s['id']=='rear-link-torque':s['instruction']=s['instruction'].replace('The unchanged upper shock mount is not part of this removal.','The upper shock mount was separately restored to56 N·m in this frame sequence; verify that recorded check.')
 if s['id']=='rear-prepare':s['instruction']='Keep the chassis independently supported with its rear wheel clear. The engine and drive chain are already removed. Protect the rear brake pedal against operation while the wheel is absent; keep the hydraulic line closed.'
 if s['id']=='rear-remove':s['instruction']='Remove the rear axle nut. Loosen both adjuster locknuts and turn the adjusting bolts inward. Support the wheel, withdraw the axle and retain both pullers and collars by side. The chain was already removed for engine access; lower the wheel clear without disturbing the hydraulic line.'
 if s['id']=='front-bar-refit':s['instruction']=s['instruction'].replace('Turn lock-to-lock to confirm no fuel-tank contact or cable/hose tension.','Check bar alignment and cable/hose clearance now; verify fuel-tank clearance after tank reinstallation.')
 if s['id']=='frame-final':s['instruction']+=' With the fuel tank installed, verify the handlebar does not contact it at either steering lock.'
 if s['id']=='front-setup':s['instruction']='Record both fork clicker settings and current height before front-end removal; this operation restores standard2 mm projection. Keep the stripped chassis independently supported with its front wheel clear. The engine and rear wheel are already removed.';s['record_required']=True
 if s['id']=='front-steering-close':s['instruction']='Check the rebuilt steering and front end now: no play or binding, smooth fork action, wheel correctly secured and firm front brake. Inspect hose/cable clearance while the remaining assemblies are still supported. Repeat whole-bike checks after the remaining fluid and startup checks are complete.'
p=emit('frame-strip-reassemble-v1','Strip and reassemble the stock chassis','Complete source-based strip to the serviceable main frame with pressed steering races/bonded pads retained, and reassembly of stock connected assemblies. Includes coordinated engine/swingarm pivot, wheels/linkage/steering, rear frame, radiators, brackets and harness routing. Engine/suspension internals and structural repair are separate. Intact control/hydraulic assembly retention requires unobstructed stock routing and adequate independent supports.',frame,['Structural frame repair, welding, paint stripping or alignment correction','Pressed steering-race removal','Internal engine/fork/shock rebuild','Modified harness, intake or hydraulic routing that prevents intact assembly removal','Hydraulic joint opening or cable-end detachment'],['Stable chassis stand plus independent engine/swingarm/component supports and helper','Source-specified steering nut and fork cap ring tools','Calibrated torque tools covering1.5–145 N·m and appropriate axle/pivot/sprocket tools','Radiator pressure tester90890-01325/YU-24460-A and adapter90890-01352/YU-33984','Fluid catch/measure containers, fuel-safe transfer equipment, port covers and labeled storage','Molybdenum-disulfide, lithium-soap, silicone greases and source-specified LOCTITE'],parts=copy.deepcopy(eng['required_parts'])+[{'name':'New upper-chain-tensioner retaining pin','purpose':'Rear-frame bolt removal disturbs the OEM one-use pin.'},{'name':'Replacement original-type harness ties','purpose':'Restore every released tape-position/routing clamp.'}],dependencies=[{'artifact':str(root/name),'sha256':hashlib.sha256((root/name).read_bytes()).hexdigest(),'kind':'source_reviewed_cutpoint_composition'} for name in ['engine-remove-refit-v1.procedure.json','steering-bearing-inspection-v1.procedure.json','swingarm-linkage-remove-refit-v1.procedure.json','rear-wheel-remove-refit-v1.procedure.json']])
p['status']='SOURCE_REVIEWED_BOUNDED_PROCEDURE';p['source']['review_status']='APPROVED';p['affected_components']=['engine_modifications','fork','shock','suspension','intake','exhaust','ecu','clutch','chain','swingarm','linkage','wheels','front_wheel','rear_wheel','brakes','front_brake','rear_brake','clamps','triple_clamps','frame','subframe','wiring']
p['entry_state']=['Assembled exact stock 2026 US standard Yamaha YZ450F with serviceable frame and supported stock routing.', 'All necessary separate engine/component repairs have defined checks and closure records; this guide does not supply their internal rebuild steps.']
p['exit_state']=['Serviceable main frame stripped with pressed steering races and bonded pads retained, inspected and reassembled.', 'All removed stock assemblies refitted, disturbed routing and fasteners checked, fluid/operating checks recorded, and unresolved defects preserved.', 'Engine and suspension internals remain separate jobs; this is not structural repair or physical validation.']
(out/'frame-strip-reassemble-v1.procedure.json').write_text(json.dumps(p,indent=2,ensure_ascii=False)+'\n',encoding='utf8');print('Reviewed full frame:',len(frame),'steps')
